using System;using System.IO;using System.IO.Compression;using System.Linq;using System.Text;using System.Collections.Generic;using System.Threading;using System.Web.Script.Serialization;
namespace PZ3D {
 static class LiveModDiscovery {
  internal const string BuddyHash="eb79b9876332010733a8e0d7ce4fe0377846059a9e28859029e2a0fb449f6cf2";
  internal sealed class Session {public string Directory,Manifest,ManifestHash;public string[] VmArguments,EnabledIds,SelectedRoots,Warnings;}
  static readonly UTF8Encoding Utf8=new UTF8Encoding(false,true);
  static string Record(string key,params string[] values){return key+string.Concat(values.Select(v=>"\t"+Convert.ToBase64String(Utf8.GetBytes(v))))+"\n";}
  internal static string[] MergeOrder(string[] ordinary,HashSet<string> required,string[] anchors){var result=ordinary.Distinct().ToList();int cursor=0;foreach(string raw in anchors){string id=raw.TrimStart('\\');int existing=result.FindIndex(x=>x.TrimStart('\\')==id);if(existing>=0)cursor=Math.Max(cursor,existing+1);else if(required.Contains(id))result.Insert(cursor++,id);}return result.ToArray();}
  internal static byte[] BuddyBytes(string file){LauncherMaintenance.NoReparse(file);if(!File.Exists(file)||new FileInfo(file).Length>33554432)throw new IOException("Buddy 运行文件缺失。");byte[] bytes=File.ReadAllBytes(file);if(LauncherComponents.Hash(bytes)!=BuddyHash)throw new IOException("当前独立启动支持已核实的 Buddy 2.3.4，请选择对应组件来源。");return bytes;}
  static void VerifyAgent(byte[] bytes){if(bytes==null||bytes.Length==0||bytes.Length>33554432)throw new IOException("启动器实时隔离组件缺失。");using(var stream=new MemoryStream(bytes))using(var zip=new ZipArchive(stream,ZipArchiveMode.Read)){if(zip.GetEntry("ozl/environment/LiveEnvironmentAgent.class")==null||zip.GetEntry("ozl/environment/LiveEnvironmentManifest.class")==null)throw new IOException("启动器实时隔离组件不完整。");}}
  internal static Session Prepare(LauncherComponents components,SaveProfiles.Entry[] ordinaryCatalog,CancellationToken token){return Prepare(components,BundledAssets.ReadOwnAsset("OrangeLive.jar"),ordinaryCatalog,token,null);}
  // bridgeRoot must be a session-owned root inside this context; caller owns its nonce/cleanup.
  internal static Session Prepare(LauncherComponents components,byte[] liveAgent,SaveProfiles.Entry[] ordinaryCatalog,CancellationToken token,string bridgeRoot,string[] ordinaryOverride=null){var c=components.Context;if(c.Mode=="steam")throw new IOException("Steam 配置不使用启动器实时隔离。");token.ThrowIfCancellationRequested();if(components.GameVersion.Major!=42)throw new IOException("此游戏版本的独立模组加载入口尚未核实；可明确选择 Steam 配置启动。");VerifyAgent(liveAgent);c.Initialize();bool vanilla=c.Mode=="vanilla";var capture=components.CaptureCurrent(token,vanilla?new string[0]:ordinaryOverride);var rows=vanilla?new LauncherComponents.Row[0]:capture.Rows.Where(x=>x.Enabled).ToArray();foreach(var row in rows)if(row.Warning!="")throw new IOException(row.Warning);
   var plan=vanilla?null:components.PlanEnabled(capture,ordinaryCatalog,token,ordinaryOverride);var required=new HashSet<string>(rows.Select(r=>r.Id));var pending=new Queue<string>(required);while(pending.Count>0){string id=pending.Dequeue();var component=rows.FirstOrDefault(r=>r.Id==id);var ordinary=(ordinaryCatalog??new SaveProfiles.Entry[0]).FirstOrDefault(r=>r.id.TrimStart('\\')==id);foreach(string dependency in component!=null?component.Requires:ordinary==null?new string[0]:ordinary.requires??new string[0])if(required.Add(dependency.TrimStart('\\')))pending.Enqueue(dependency.TrimStart('\\'));}if(plan!=null){var available=new HashSet<string>(plan.mods.Select(id=>id.TrimStart('\\')));foreach(string dependency in required)if(!available.Contains(dependency))throw new IOException("所选组件缺少依赖 "+dependency+"，请选择或下载此项后重试。");}byte[] buddy=null;var buddyRow=rows.SingleOrDefault(r=>r.Id=="ZombieBuddy");if(buddyRow!=null)buddy=BuddyBytes(buddyRow.Jar??Path.Combine(buddyRow.SourceRoot,"libs","ZombieBuddy.jar"));if(rows.Any(r=>r.Jar!=null&&r.Id!="ZombieBuddy")&&buddy==null)throw new IOException("启用的 Java 组件需要选择 ZombieBuddy 来源。");
   foreach(var row in rows.Where(r=>r.Jar!=null&&r.Id!="ZombieBuddy"))if(row.Decision!=true)throw new IOException(row.Name+(row.Decision==false?"：当前 Java 文件已拒绝授权。":"：当前 Java 文件需要授权，请在组件中心确认。"));
   c.Initialize();string session=Path.Combine(c.RuntimeDirectory,"live-"+Guid.NewGuid().ToString("N").Substring(0,12));Directory.CreateDirectory(session);try{
    string mods=Path.Combine(session,"mods"),config=Path.Combine(session,"buddy");Directory.CreateDirectory(mods);Directory.CreateDirectory(config);string[] managed=capture.Managed.Concat(rows.Select(row=>row.Id)).Concat(new[]{"OrangeLauncherSession"}).Distinct().ToArray();string[] enabled=vanilla?new string[0]:MergeOrder((ordinaryOverride??capture.OrdinaryIds??SaveProfiles.DefaultMods(capture.Ordinary)).Where(id=>!capture.Managed.Contains(id.TrimStart('\\'))).ToArray(),required,plan.mods);
    if(bridgeRoot!=null){bridgeRoot=Path.GetFullPath(bridgeRoot);LauncherMaintenance.NoReparse(bridgeRoot);if(!bridgeRoot.StartsWith(c.Root+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)||!Directory.Exists(bridgeRoot))throw new IOException("启动桥接不在此配置内。");enabled=enabled.Concat(new[]{"OrangeLauncherSession"}).ToArray();}
    byte[] original=capture.Ordinary;LauncherComponents.Atomic(Path.Combine(mods,"default.txt"),SaveProfiles.ReplaceDefaultMods(original,enabled));LauncherComponents.Atomic(Path.Combine(mods,"loaded.txt"),Utf8.GetBytes(string.Join("\n",enabled)));
    string agent=Path.Combine(session,"OrangeLive.jar");LauncherComponents.Atomic(agent,liveAgent);var body=new StringBuilder("OZLLIVE1\n").Append(Record("game",c.Game)).Append(Record("user",c.User)).Append(Record("context",c.Root)).Append(Record("choices",session)).Append(Record("vanilla",vanilla?"true":"false"));foreach(string id in managed)body.Append(Record("managed",id));

    foreach(string id in enabled)body.Append(Record("order",id.TrimStart('\\')));foreach(string id in enabled.Where(value=>required.Contains(value.TrimStart('\\'))))body.Append(Record("component",id.TrimStart('\\')));body.Append(Record("override",ordinaryOverride==null?"false":"true"));if(ordinaryOverride!=null)foreach(string id in ordinaryOverride)body.Append(Record("ordinary",id));
    foreach(var row in rows.OrderBy(r=>Array.IndexOf(enabled,r.Id)))body.Append(Record("selected",row.Id,row.SourceRoot));if(bridgeRoot!=null){body.Append(Record("selected","OrangeLauncherSession",bridgeRoot));body.Append(Record("component","OrangeLauncherSession"));}foreach(var row in rows.Where(r=>r.Jar!=null&&r.Id!="ZombieBuddy")){if(LauncherComponents.HashFile(row.Jar)!=row.Sha256)throw new IOException(row.Name+"：Java 文件在准备期间已更新，请重试。");body.Append(Record("jar",row.Jar,row.Package,row.Sha256,"true"));}
    string buddyPath=Path.Combine(session,"ZombieBuddy.jar");if(buddy!=null){LauncherComponents.Atomic(buddyPath,buddy);body.Append(Record("buddy",buddyPath,BuddyHash));}
    var json=new JavaScriptSerializer();LauncherComponents.Atomic(Path.Combine(config,"config.json"),Utf8.GetBytes("{\"trusted_authors\":[],\"preload_mods\":{},\"auto_fix_mod_order\":false,\"fix_approval_dialog_cursor\":false}"));LauncherComponents.Atomic(Path.Combine(config,"mod_approvals.json"),Utf8.GetBytes(json.Serialize(new{formatVersion=2,mods=rows.Where(r=>r.Jar!=null&&r.Id!="ZombieBuddy").Select(r=>new{id=r.Id,jar_hash=r.Sha256,decision=true}).ToArray()})));
    string manifest=Path.Combine(session,"live.manifest");byte[] manifestBytes=Utf8.GetBytes(body.ToString());LauncherComponents.Atomic(manifest,manifestBytes);string hash=LauncherComponents.Hash(manifestBytes);var arguments=new List<string>{"-Dozl.live.manifest="+manifest,"-Dozl.live.sha256="+hash,"-javaagent:"+agent};if(buddy!=null){arguments.Add("-Dzb.config_dir="+config);arguments.Add("-javaagent:"+buddyPath+"=prop_prefix=zb,policy=deny-new");}components.RequireCurrent(capture);token.ThrowIfCancellationRequested();return new Session{Directory=session,Manifest=manifest,ManifestHash=hash,Warnings=plan==null?new string[0]:plan.errors.Concat(plan.warnings).Concat(plan.violations).Distinct().ToArray(),VmArguments=arguments.ToArray(),EnabledIds=enabled,SelectedRoots=rows.Select(r=>r.SourceRoot).Concat(bridgeRoot==null?new string[0]:new[]{bridgeRoot}).ToArray()};
   }catch{LauncherMaintenance.NoReparse(session);System.IO.Directory.Delete(session,true);throw;}
  }
 }
}
